html {
  scrollbar-width: auto;
  scrollbar-color: var(--skye-cyan) rgba(255, 255, 255, 0.12);
}

::-webkit-scrollbar {
  width: 14px;
  height: 14px;
}

::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.1);
