    linear-gradient(180deg, rgba(5, 5, 11, 0.94), rgba(3, 3, 7, 0.98)),
    radial-gradient(1200px 760px at 14% 4%, rgba(138, 99, 255, 0.2), transparent 58%),
    radial-gradient(1100px 760px at 82% 16%, rgba(39, 242, 255, 0.12), transparent 58%),
    radial-gradient(900px 660px at 55% 92%, rgba(201, 168, 76, 0.12), transparent 60%);
}

.skyesol-living-page .bg-background {
  background-color: color-mix(in oklab, var(--background) 88%, transparent);
}

.skye-motion-chrome {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.skye-motion-chrome__progress {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 90;
  width: 100%;
  height: 4px;
  transform: scaleX(var(--skye-scroll-progress));
  transform-origin: left center;
  background: linear-gradient(90deg, var(--skye-gold), var(--skye-cyan), var(--skye-violet));
  box-shadow: 0 0 22px rgba(39, 242, 255, 0.42);
}

.skyesol-living-field,
.skyesol-grain,
.skyesol-scanline {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.skyesol-living-field {
  opacity: 0.72;
}

.skyesol-grain {
  opacity: 0.1;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.62'/%3E%3C/svg%3E");
}

.skyesol-scanline {
  opacity: 0.045;
  background: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.22),
    rgba(255, 255, 255, 0.22) 1px,
    transparent 1px,
    transparent 6px
  );
}

.skye-motion-chrome__label {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 75;
  max-width: min(280px, calc(100vw - 36px));
  border: 1px solid rgba(255, 215, 106, 0.3);
  border-radius: 999px;
  padding: 9px 12px;
  background: rgba(5, 3, 11, 0.74);
  color: rgba(255, 248, 231, 0.86);
  font-size: 11px;
  font-weight: 900;
  line-height: 1.1;
  text-transform: uppercase;
  backdrop-filter: blur(14px);
}

.neon-gradient-text {
  background: linear-gradient(92deg, #fff8e7 0%, var(--skye-gold) 30%, var(--skye-cyan) 62%, var(--skye-violet) 88%, #fff8e7 100%);
  background-size: 220% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: neonTitleShimmer 7s linear infinite;
}

.neon-glow-panel {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.035));
  box-shadow:
    0 24px 80px rgba(0, 0, 0, 0.32),
    0 0 34px rgba(39, 242, 255, 0.1);
}

.neon-glow-panel::before {
  content: "";
  position: absolute;
  inset: -80% -20%;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.18), transparent);
  transform: rotate(18deg);
  animation: neonSweep 7s ease-in-out infinite;
}

.neon-magnetic {
  transition:
    transform 0.22s ease,
    border-color 0.22s ease,
    box-shadow 0.22s ease;
}

.neon-magnetic:hover {
  transform: translateY(-3px) scale(1.015);
  border-color: rgba(39, 242, 255, 0.62);
  box-shadow:
    0 18px 54px rgba(39, 242, 255, 0.14),
    0 0 28px rgba(255, 215, 106, 0.16);
}

@keyframes neonTitleShimmer {
  from {
    background-position: 0% center;
  }
  to {
    background-position: 220% center;
  }
}

@keyframes neonSweep {
  0%,
  62% {
    translate: -120% 0;
  }
  100% {
    translate: 120% 0;
  }
}

@media (pointer: coarse), (max-width: 760px) {
  .skye-motion-chrome__label {
    right: 12px;
    bottom: 12px;
    max-width: calc(100vw - 24px);
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }

  .skyesol-living-field,
  .skyesol-scanline {
    display: none;
  }
}


