import { ImageResponse } from "next/og";
import { allPosts } from "content-collections";
import { DATA } from "@/data/resume";

export const runtime = "edge";

export const alt = "Blog Post";
export const size = {
    width: 1200,
    height: 630,
};
export const contentType = "image/png";

const getFontData = async () => {
    try {
        const [cabinetGrotesk, clashDisplay] = await Promise.all([
            fetch(
                new URL(
                    "../../../../public/fonts/CabinetGrotesk-Medium.ttf",
                    import.meta.url
                )
            ).then((res) => res.arrayBuffer()),
            fetch(
                new URL(
                    "../../../../public/fonts/ClashDisplay-Semibold.ttf",
                    import.meta.url
                )
            ).then((res) => res.arrayBuffer()),
        ]);
        return { cabinetGrotesk, clashDisplay };
    } catch (error) {
        console.error("Failed to load fonts:", error);
        return null;
    }
};

const styles = {
    outerWrapper: {
        height: "100%",
        width: "100%",
        display: "flex",
        flexDirection: "column",
        backgroundColor: "#ffffff",
        position: "relative",
    },
    middleWrapper: {
        height: "100%",
        width: "100%",
        display: "flex",
        flexDirection: "column",
        backgroundColor: "#ffffff",
        position: "relative",
        padding: "40px",
    },
    wrapper: {
        height: "100%",
        width: "100%",
        display: "flex",
        flexDirection: "column",
        backgroundColor: "#fafafa",
        position: "relative",
        padding: "40px",
        border: "1px solid #e5e5e5",
        borderRadius: "12px",
    },
    imageSection: {
        position: "absolute",
        top: "40px",
        left: "40px",
        display: "flex",
        alignItems: "center",
        zIndex: "2",
    },
    mainContainer: {
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
        justifyContent: "flex-end",
        height: "100%",
        width: "100%",
        position: "relative",
        zIndex: "1",
    },
    image: {
        width: "140px",
        height: "140px",
        borderRadius: "24px",
        border: "4px solid #e5e5e5",
        objectFit: "cover",
    },
    title: {
        fontFamily: "Clash Display",
        fontSize: "48px",
        fontWeight: "600",
        lineHeight: "1.1",
        textAlign: "left",
        color: "#000000",
        marginBottom: "16px",
        letterSpacing: "-0.02em",
        maxWidth: "900px",
    },
    description: {
        fontSize: "20px",
        fontWeight: "400",
        lineHeight: "1.5",
        textAlign: "left",
        maxWidth: "800px",
        color: "#404040",
        marginBottom: "16px",
        textWrap: "balance",
    },
    date: {
        fontSize: "16px",
        fontWeight: "400",
        lineHeight: "1.5",
        textAlign: "left",
        color: "#666666",
        marginBottom: "32px",
    },
} as const;

export default async function Image({
    params,
}: {
    params: Promise<{ slug: string }>;
}) {
    try {
        const fontData = await getFontData();
        const { slug } = await params;
        const post = allPosts.find((p) => p._meta.path.replace(/\.mdx$/, "") === slug);
        const imageUrl = DATA.avatarUrl
            ? new URL(DATA.avatarUrl, DATA.url).toString()
            : undefined;

        if (!post) {
            return new ImageResponse(
                (
                    <div style={styles.outerWrapper}>
                        <div style={styles.middleWrapper}>
                            <div style={styles.wrapper}>
                                {imageUrl && (
                                    <div style={styles.imageSection}>
                                        <img src={imageUrl} alt="Blog Post" style={styles.image} />
                                    </div>
                                )}
                                <div style={styles.mainContainer}>
                                    <div style={styles.title}>Post Not Found</div>
                                </div>
                            </div>
                        </div>
                    </div>
                ),
                {
                    ...size,
                    fonts: fontData
                        ? [
                            {
                                name: "Clash Display",
                                data: fontData.clashDisplay,
                                weight: 600,
                                style: "normal",
                            },
                        ]
                        : undefined,
                }
            );
        }

        const title = post.title;
        const description = post.summary || "";
        const publishedDate = post.publishedAt
            ? new Date(post.publishedAt).toLocaleDateString("en-US", {
                year: "numeric",
                month: "long",
                day: "numeric",
                timeZone: "UTC",
            })
            : "";

        return new ImageResponse(
            (
                <div style={styles.outerWrapper}>
                    <div style={styles.middleWrapper}>
                        <div style={styles.wrapper}>
                            {imageUrl && (
                                <div style={styles.imageSection}>
                                    <img src={imageUrl} alt={title} style={styles.image} />
                                </div>
                            )}
                            <div style={styles.mainContainer}>
                                <div style={styles.title}>{title}</div>
                                {description && (
                                    <div style={styles.description}>{description}</div>
                                )}
                                {publishedDate && <div style={styles.date}>{publishedDate}</div>}
                            </div>
                        </div>
                    </div>
                </div>
            ),
            {
                ...size,
                fonts: fontData
                    ? [
                        {
                            name: "Cabinet Grotesk",
                            data: fontData.cabinetGrotesk,
                            weight: 400,
                            style: "normal",
                        },
                        {
                            name: "Cabinet Grotesk",
                            data: fontData.cabinetGrotesk,
                            weight: 700,
                            style: "normal",
                        },
                        {
                            name: "Clash Display",
                            data: fontData.clashDisplay,
                            weight: 600,
                            style: "normal",
                        },
                    ]
                    : undefined,
            }
        );
    } catch (error) {
        console.error("Error generating OpenGraph image:", error);
        return new Response(
            `Failed to generate image: ${error instanceof Error ? error.message : "Unknown error"}`,
            {
                status: 500,
            }
        );
    }
